<script>
  let { phases = [], laneSource = null } = $props()
</script>
<div class="phase-wrap" title={laneSource == null ? 'agent-lane colouring unavailable — the record carries no phase↔agent link' : undefined}>
  <div class="dots" aria-label="phases">{#each phases as phase (phase.id ?? phase.seq)}<span class:running={phase.status === 'running'} class="dot" class:status-ok={phase.lane == null && phase.status === 'ok'} class:status-fail={phase.lane == null && phase.status === 'fail'} class:status-running={phase.lane == null && phase.status === 'running'} class:status-skipped={phase.lane == null && phase.status === 'skipped'} class:lane-dot={phase.lane != null} style={phase.lane == null ? undefined : `--lane-color: var(--lane-${phase.lane})`} title={`${phase.name} — ${phase.status} — ${phase.duration_ms ?? 'pending'}ms`}></span>{/each}</div>
  {#if laneSource == null}<small class="unavailable" aria-label="agent-lane colouring unavailable — the record carries no phase↔agent link">agent-lane colouring unavailable</small>{/if}
</div>
<style>.phase-wrap { display:flex; align-items:center; gap:.5rem; }.dots { display:flex; gap:.3rem; }.dot { width:.75rem; height:.75rem; border-radius:50%; }.lane-dot { background:var(--lane-color); }.status-ok { background:var(--status-ok); }.status-fail { background:var(--status-fail); }.status-running { background:var(--status-running); }.status-skipped { background:var(--status-skipped); }.running { animation:pulse 1.2s infinite; }.unavailable { color:var(--muted); font-size:.7rem; white-space:nowrap; } @keyframes pulse { 50% { opacity:.35; } }</style>
